(6364655, 941584, 115145, '<td valign="top">I like it but it lacks a focal point.</td>', 'I like it but it lacks a focal point.', '2011-03-27 22:12:16.000000', NULL, 1),
(6364656, 941094, 115145, '<td valign="top">I wish I could see more of the bug, but otherwise very well done.</td>', 'I wish I could see more of the bug, but otherwise very well done.', '2011-03-27 22:13:05.000000', NULL, 1),
