(6364664, 942091, 115145, '<td valign="top">The exposure is a little flat, kinda dull.</td>', 'The exposure is a little flat, kinda dull.', '2011-03-27 22:25:05.000000', NULL, 1),
(6364667, 941617, 115145, '<td valign="top">I hate to be critical but I usually appreciate it. I love this picture but given the theme for the contest this picture doesn''t cut it. There is no real focal point that truly grips my eye.</td>', 'I hate to be critical but I usually appreciate it. I love this picture but given the theme for the contest this picture doesn''t cut it. There is no real focal point that truly grips my eye.', '2011-03-27 22:27:45.000000', NULL, 1),
