INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6367127, 942211, 54645, '<td valign="top">Not so subtle is it? I enjoyed the comments, and yes a lovely smile.</td>', 'Not so subtle is it? I enjoyed the comments, and yes a lovely smile.', '2011-03-30 03:37:14.000000', NULL, 0),
(6367137, 942189, 117474, '<td valign="top">I disagree with the person who said the background should have been brighter. The contrast between that and the ball really makes the ball stand out, and reinforces it as the focal point. <br/> <br/>There was something about this that didn''t seem... right to me, and I can''t put my finger on it. First I thought it was that it wasn''t sharp, which it is, or perhaps its the lighting. Maybe it''s the dark patch of ball by the second t on its branding. Something about this didn''t stand right with me, so I didn''t vote on it until I found out what. Which I still haven''t. Maybe a darker tee? This is really annoying me, actually, that I can''t figure out what it is about this shot that''s getting to me! Ahhh!<br/> <br/>Not a bad score. Good job.</td>', 'I disagree with the person who said the background should have been brighter. The contrast between that and the ball really makes the ball stand out, and reinforces it as the focal point.  There was something about this that didn''t seem... right to me, and I can''t put my finger on it. First I thought it was that it wasn''t sharp, which it is, or perhaps its the lighting. Maybe it''s the dark patch of ball by the second t on its branding. Something about this didn''t stand right with me, so I didn''t vote on it until I found out what. Which I still haven''t. Maybe a darker tee? This is really annoying me, actually, that I can''t figure out what it is about this shot that''s getting to me! Ahhh! Not a bad score. Good job.', '2011-03-30 03:40:54.000000', NULL, 0),
(6367157, 941617, 16106, '<td valign="top">My highest score in the challenge, also given to the first and second place winners, but what is this lovely shot doing down here at 18th? Oh well, it is still a lovely shot.<br/><br/><i>Message edited by author 2011-03-30 03:05:11.</i></td>', 'My highest score in the challenge, also given to the first and second place winners, but what is this lovely shot doing down here at 18th? Oh well, it is still a lovely shot.', '2011-03-30 04:04:38.000000', '2011-03-30 04:05:11.000000', 0),
(6367245, 941916, 33361, '<td valign="top">Awesome LIVER LIPS! ; ))</td>', 'Awesome LIVER LIPS! ; ))', '2011-03-30 06:02:59.000000', NULL, 0),
(6367267, 941526, 127262, '<td valign="top">My first challenge and I am happy with the results, thanks for the comments left.<br/></td>', 'My first challenge and I am happy with the results, thanks for the comments left.', '2011-03-30 06:43:09.000000', NULL, 0),
(6367275, 942241, 67152, '<td valign="top">I am surprised to see this one down here.  I think you did a great job to convey the intent of the challenge, with the lines leading to her eyes and face, etc.</td>', 'I am surprised to see this one down here.  I think you did a great job to convey the intent of the challenge, with the lines leading to her eyes and face, etc.', '2011-03-30 07:03:08.000000', NULL, 0),
